mapper.select:
SELECT q.*, c.name AS category_name, b.name AS bank_name
FROM question q
LEFT JOIN category c ON c.id = q.category_id
LEFT JOIN bank b ON b.id = q.bank_id

    q.user_id = #{userId}

        AND (q.title LIKE CONCAT('%', #{q.keyword}, '%') OR q.tags LIKE CONCAT('%', #{q.keyword}, '%'))


        AND (q.category_id = #{q.categoryId}
             OR q.category_id IN (SELECT id FROM category WHERE parent_id = #{q.categoryId}))

    AND q.bank_id = #{q.bankId}
    AND q.type = #{q.type}
    AND q.difficulty = #{q.difficulty}

        AND q.tags LIKE CONCAT('%', #{q.tag}, '%')


ORDER BY q.id DESC

SELECT q.*
FROM question q

    INNER JOIN wrong_question wq ON wq.question_id = q.id
        AND wq.user_id = #{userId} AND wq.mastered = 0


    q.user_id = #{userId}

        AND (q.category_id = #{categoryId}
             OR q.category_id IN (SELECT id FROM category WHERE parent_id = #{categoryId}))

    AND q.bank_id = #{bankId}
    AND q.difficulty = #{difficulty}
    AND q.type = #{type}

ORDER BY q.id
LIMIT #{limit}

SELECT q.id
FROM question q

    INNER JOIN wrong_question wq ON wq.question_id = q.id
        AND wq.user_id = #{userId} AND wq.mastered = 0


    q.user_id = #{userId}

        AND (q.category_id = #{categoryId}
             OR q.category_id IN (SELECT id FROM category WHERE parent_id = #{categoryId}))

    AND q.bank_id = #{bankId}
    AND q.difficulty = #{difficulty}
    AND q.type = #{type}

LIMIT #{limit}

mapper.update:
UPDATE question
category_id = #{categoryId}, bank_id = #{bankId}, type = #{type}, title = #{title}, options = #{options}, answer = #{answer}, analysis = #{analysis}, difficulty = #{difficulty}, tags = #{tags}, source = #{source},
WHERE id = #{id}
